import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.io.*;import java.util.*;
public class RegistrationApp extends JFrame {
 private final JTextField studentId=new JTextField(12),name=new JTextField(16); private final JComboBox<String> event=new JComboBox<>(new String[]{"Music Night","Tech Fest","Cultural Day"}); private final JComboBox<String> filter=new JComboBox<>(new String[]{"All","Music Night","Tech Fest","Cultural Day"});private final RegistrationService service=new RegistrationService();
 private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Student ID","Name","Event","Registered"},0);private final JTable table=new JTable(model);private int page=0;private final int size=50;
 public RegistrationApp(){super("Campus Event Registration");setLayout(new BorderLayout());JMenuBar mb=new JMenuBar();JMenu file=new JMenu("File");JMenuItem export=new JMenuItem("Export CSV");export.addActionListener(e->exportCsv());file.add(export);mb.add(file);setJMenuBar(mb);
 JPanel form=new JPanel(new FlowLayout(FlowLayout.LEFT));form.add(new JLabel("Student ID"));form.add(studentId);form.add(new JLabel("Name"));form.add(name);form.add(event);JButton register=new JButton("Register");form.add(register);JPanel tools=new JPanel();tools.add(new JLabel("Filter"));tools.add(filter);JButton apply=new JButton("Apply"),prev=new JButton("Prev"),next=new JButton("Next");tools.add(apply);tools.add(prev);tools.add(next);add(form,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);add(tools,BorderLayout.SOUTH);
 register.addActionListener(e->register());apply.addActionListener(e->{page=0;load();});filter.addActionListener(e->{page=0;load();});prev.addActionListener(e->{if(page>0){page--;load();}});next.addActionListener(e->{page++;load();});setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(850,500);setLocationRelativeTo(null);load();}
 private void register(){String sid=studentId.getText().trim(),nm=name.getText().trim(),ev=(String)event.getSelectedItem();if(!sid.matches("[A-Za-z0-9-]{3,24}")||nm.isBlank()){JOptionPane.showMessageDialog(this,"Enter a valid student ID and name.","Invalid input",JOptionPane.ERROR_MESSAGE);return;}new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{service.register(sid,nm,ev);return null;}protected void done(){try{get();JOptionPane.showMessageDialog(RegistrationApp.this,"Registration saved.");page=0;load();}catch(Exception ex){Throwable cause=ex.getCause();String message=cause instanceof DuplicateRegistrationException?cause.getMessage():"Database operation failed: "+cause;JOptionPane.showMessageDialog(RegistrationApp.this,message,"Registration",JOptionPane.ERROR_MESSAGE);}}}.execute();}
 private void load(){String selected=(String)filter.getSelectedItem();new SwingWorker<java.util.List<Object[]>,Void>(){protected java.util.List<Object[]> doInBackground()throws Exception{return service.page(selected.equals("All")?null:selected,size,page*size);}protected void done(){try{model.setRowCount(0);for(Object[] row:get())model.addRow(row);if(model.getRowCount()==0&&page>0){page--;}}catch(Exception e){JOptionPane.showMessageDialog(RegistrationApp.this,"Could not load registrations: "+e.getCause());}}}.execute();}
 private void exportCsv(){JFileChooser chooser=new JFileChooser();if(chooser.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try(PrintWriter out=new PrintWriter(chooser.getSelectedFile())){for(int c=0;c<model.getColumnCount();c++)out.print((c==0?"":",")+quote(model.getColumnName(c)));out.println();for(int r=0;r<model.getRowCount();r++){for(int c=0;c<model.getColumnCount();c++)out.print((c==0?"":",")+quote(String.valueOf(model.getValueAt(r,c))));out.println();}}catch(IOException e){JOptionPane.showMessageDialog(this,e.getMessage());}}
 private static String quote(String s){return "\""+s.replace("\"","\"\"")+"\"";}public static void main(String[]a){SwingUtilities.invokeLater(()->new RegistrationApp().setVisible(true));}
}
